<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/_layout.php'; $u=require_admin(); $ok=$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$action=$_POST['action']??'';if($action==='settings'){foreach(['maintenance_mode','maintenance_message','portal_registration','security_session_hours'] as $k){$v=(string)($_POST[$k]??(($k==='maintenance_mode'||$k==='portal_registration')?'0':''));$q=db()->prepare('INSERT INTO app_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$q->execute([$k,$v]);}audit_log('security.settings.update','settings',null,'Production/security settings updated.');$ok='Settings saved.';}if($action==='clear_audit'){db()->exec("DELETE FROM admin_audit_log WHERE created_at < DATE_SUB(NOW(), INTERVAL 180 DAY)");audit_log('audit.cleanup');$ok='Old audit entries removed.';}}catch(Throwable $e){$err=$e->getMessage();}}
$settings=[];foreach(['maintenance_mode','maintenance_message','portal_registration','security_session_hours'] as $k)$settings[$k]=app_setting($k,'');$logs=db()->query('SELECT a.*,u.name admin_name FROM admin_audit_log a LEFT JOIN users u ON u.id=a.admin_user_id ORDER BY a.id DESC LIMIT 100')->fetchAll();
admin_head($u,'Security & Production','security');?>
<?php if($ok):?><div class="notice success"><?=e($ok)?></div><?php endif?><?php if($err):?><div class="notice error"><?=e($err)?></div><?php endif?>
<section class="card settings-card"><div class="cardhead"><b>PRODUCTION CONTROLS</b></div><form method="post" class="admin-form-grid" style="padding:20px"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="settings"><label>Maintenance mode<select name="maintenance_mode"><option value="0" <?=$settings['maintenance_mode']==='0'?'selected':''?>>Off</option><option value="1" <?=$settings['maintenance_mode']==='1'?'selected':''?>>On — admins bypass</option></select></label><label>Customer registration<select name="portal_registration"><option value="1" <?=$settings['portal_registration']==='1'?'selected':''?>>Enabled</option><option value="0" <?=$settings['portal_registration']==='0'?'selected':''?>>Disabled</option></select></label><label>Session target (hours)<input name="security_session_hours" type="number" min="1" max="168" value="<?=e($settings['security_session_hours'])?>"></label><label class="fullfield">Maintenance message<textarea name="maintenance_message" rows="3"><?=e($settings['maintenance_message'])?></textarea></label><div><button class="btn primary">Save production settings</button></div></form></section>
<section class="card"><div class="cardhead"><b>ADMIN AUDIT LOG</b><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="clear_audit"><button class="btn">Remove entries older than 180 days</button></form></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Time</th><th>Admin</th><th>Action</th><th>Target</th><th>IP</th><th>Details</th></tr></thead><tbody><?php foreach($logs as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['admin_name']?:'System')?></td><td><b><?=e($r['action'])?></b></td><td><?=e(trim(($r['target_type']??'').' '.($r['target_id']??'')))?></td><td><?=e($r['ip_address'])?></td><td><?=e($r['details'])?></td></tr><?php endforeach?><?php if(!$logs):?><tr><td colspan="6" class="muted">No audit events yet.</td></tr><?php endif?></tbody></table></div></section>
<?php admin_foot(); ?>
